//! True Random Number Generator (TRNG) driver.

use core::future::poll_fn;
use core::marker::PhantomData;
use core::ops::Not;
use core::task::Poll;

use embassy_hal_internal::drop::OnDrop;
use embassy_hal_internal::{Peri, PeripheralType};
use embassy_sync::waitqueue::AtomicWaker;

use crate::interrupt::typelevel::{Binding, Interrupt};
use crate::peripherals::TRNG;
use crate::{interrupt, pac};

/// Private access to the singleton register block and async waiter.
trait SealedInstance {
    /// Returns the raw TRNG register block.
    fn regs() -> pac::trng::Trng;
    /// Returns the one-waiter registration shared with the IRQ handler.
    fn waker() -> &'static AtomicWaker;
}

/// TRNG peripheral instance.
#[allow(private_bounds)]
pub trait Instance: SealedInstance + PeripheralType {
    /// Interrupt for this peripheral.
    type Interrupt: Interrupt;
}

impl SealedInstance for TRNG {
    /// Returns the sole RP2350 TRNG register block.
    fn regs() -> rp_pac::trng::Trng { pac::TRNG }

    /// Returns this peripheral's static waiter.
    fn waker() -> &'static AtomicWaker {
        /// IRQ-to-fill future wake registration; peripheral ownership allows one active waiter.
        static WAKER: AtomicWaker = AtomicWaker::new();
        &WAKER
    }
}

impl Instance for TRNG {
    /// NVIC interrupt carrying EHR-ready and health-test events.
    type Interrupt = interrupt::typelevel::TRNG_IRQ;
}

#[derive(Copy, Clone, Debug)]
/// TRNG ROSC Inverter chain length options.
pub enum InverterChainLength {
    /// Hardware chain selector0 (shortest setting), not a disabled RNG.
    None = 0,
    /// Hardware chain selector1, used by the default configuration.
    One,
    /// Hardware chain selector2.
    Two,
    /// Hardware chain selector3.
    Three,
    /// Hardware chain selector4 (longest exposed setting).
    Four,
}

impl From<InverterChainLength> for u8 {
    /// Returns the register selector encoded by `value`.
    fn from(value: InverterChainLength) -> Self { value as u8 }
}

/// TRNG health-test, ring-oscillator and sampling settings; register values are not range-validated.
/// Default uses enabled health checks, chain setting1 and sample count25. Longer sampling reduces
/// throughput and may reduce health-test retries; no setting here establishes an entropy certification.
/// See [RP2350 TRNG registers](https://github.com/raspberrypi/pico-sdk/blob/master/src/rp2350/hardware_regs/include/hardware/regs/trng.h).
#[non_exhaustive]
#[derive(Copy, Clone, Debug)]
pub struct Config {
    /// Bypass TRNG autocorrelation test
    pub disable_autocorrelation_test: bool,
    /// Bypass CRNGT test
    pub disable_crngt_test: bool,
    /// When set, the Von-Neuman balancer is bypassed (including the
    /// 32 consecutive bits test)
    pub disable_von_neumann_balancer: bool,
    /// Sets the number of rng_clk cycles between two consecutive
    /// ring oscillator samples.
    /// Note: If the von Neumann decorrelator is bypassed, the minimum value for
    /// sample counter must not be less than seventeen
    pub sample_count: u32,
    /// Selects the number of inverters (out of four possible
    /// selections) in the ring oscillator (the entropy source). Higher values select
    /// longer inverter chain lengths.
    pub inverter_chain_length: InverterChainLength,
}

impl Default for Config {
    /// Returns enabled health checks, sample count25 and chain selector1.
    fn default() -> Self {
        Config {
            // WARNING: Disabling these tests increases likelihood of poor rng results.
            disable_autocorrelation_test: false,
            disable_crngt_test: false,
            disable_von_neumann_balancer: false,
            sample_count: 25,
            inverter_chain_length: InverterChainLength::One,
        }
    }
}

/// True Random Number Generator Driver for RP2350
///
/// This driver provides async and blocking options.
///
/// See [Config] for configuration details.
///
/// Usage example:
/// ```no_run
/// use embassy_executor::Spawner;
/// use embassy_rp::trng::Trng;
/// use embassy_rp::peripherals::TRNG;
/// use embassy_rp::bind_interrupts;
///
/// bind_interrupts!(struct Irqs {
///     TRNG_IRQ => embassy_rp::trng::InterruptHandler<TRNG>;
/// });
///
/// #[embassy_executor::main]
/// async fn main(spawner: Spawner) {
///     let peripherals = embassy_rp::init(Default::default());
///     let mut trng = Trng::new(peripherals.TRNG, Irqs, embassy_rp::trng::Config::default());
///
///     let mut randomness = [0u8; 58];
///     loop {
///         trng.fill_bytes(&mut randomness).await;
///         assert_ne!(randomness, [0u8; 58]);
///     }
/// }
/// ```
pub struct Trng<'d, T: Instance> {
    /// Exclusive peripheral ownership for the driver lifetime.
    phantom: PhantomData<&'d mut T>,
    /// Configuration reapplied after an autocorrelation reset.
    config: Config,
}

/// 12.12.1. Overview
/// On request, the TRNG block generates a block of 192 entropy bits generated by automatically processing a series of
/// periodic samples from the TRNG block’s internal Ring Oscillator (ROSC).
const TRNG_BLOCK_SIZE_BITS: usize = 192;
/// Byte capacity of one complete six-register entropy result.
const TRNG_BLOCK_SIZE_BYTES: usize = TRNG_BLOCK_SIZE_BITS / 8;

impl<'d, T: Instance> Trng<'d, T> {
    /// Claims `_trng` and IRQ binding `_irq`, applies `config`, and returns the initialized driver.
    /// Does not start entropy generation; supplied register values are written without validation.
    pub fn new(
        _trng: Peri<'d, T>,
        _irq: impl Binding<T::Interrupt, InterruptHandler<T>> + 'd,
        config: Config,
    ) -> Self {
        let trng = Trng {
            phantom: PhantomData,
            config,
        };
        trng.initialize_rng();
        trng
    }

    /// Enables the ring oscillator to begin/continue entropy generation.
    fn start_rng(&self) {
        let regs = T::regs();
        let source_enable_register = regs.rnd_source_enable();
        // Enable TRNG ROSC
        source_enable_register.write(|w| w.set_rnd_src_en(true));
    }

    /// Disables the source and resets the accumulated-bit counter.
    fn stop_rng(&self) { Self::stop_rng_inner(); }

    /// Stops the singleton source and resets its bit counter, including from a cancellation guard.
    fn stop_rng_inner() {
        let regs = T::regs();
        let source_enable_register = regs.rnd_source_enable();
        source_enable_register.write(|w| w.set_rnd_src_en(false));
        let reset_bits_counter_register = regs.rst_bits_counter();
        reset_bits_counter_register.write(|w| w.set_rst_bits_counter(true));
    }

    /// Unmasks EHR-ready at the peripheral and applies stored chain/sample/test settings; NVIC remains separate.
    fn initialize_rng(&self) {
        let regs = T::regs();

        regs.rng_imr().write(|w| w.set_ehr_valid_int_mask(false));

        let trng_config_register = regs.trng_config();
        trng_config_register.write(|w| {
            w.set_rnd_src_sel(self.config.inverter_chain_length.clone().into());
        });

        let sample_count_register = regs.sample_cnt1();
        sample_count_register.write(|w| {
            *w = self.config.sample_count;
        });

        let debug_control_register = regs.trng_debug_control();
        debug_control_register.write(|w| {
            w.set_auto_correlate_bypass(self.config.disable_autocorrelation_test);
            w.set_trng_crngt_bypass(self.config.disable_crngt_test);
            w.set_vnc_bypass(self.config.disable_von_neumann_balancer);
        });
    }

    /// Enables the bound NVIC line on the current core; handler ownership is required from construction.
    fn enable_irq(&self) { unsafe { T::Interrupt::enable() } }

    /// Spins until EHR data is valid, resetting/restarting after autocorrelation failure.
    /// No deadline; an idle invalid result without autocorrelation failure panics.
    fn blocking_wait_for_successful_generation(&self) {
        let regs = T::regs();

        let trng_busy_register = regs.trng_busy();
        let trng_valid_register = regs.trng_valid();

        let mut success = false;
        while success.not() {
            while trng_busy_register.read().trng_busy() {}
            if trng_valid_register.read().ehr_valid().not() {
                if regs.rng_isr().read().autocorr_err() {
                    regs.trng_sw_reset().write(|w| w.set_trng_sw_reset(true));
                    // Fixed delay is required after TRNG soft reset. This read is sufficient.
                    regs.trng_sw_reset().read();
                    self.initialize_rng();
                    self.start_rng();
                } else {
                    panic!("RNG not busy, but ehr is not valid!")
                }
            } else {
                success = true
            }
        }
    }

    /// Copies all six EHR words into `buffer` in native byte order; the last read consumes the block.
    /// Caller must first observe a valid result.
    fn read_ehr_registers_into_array(
        &mut self,
        buffer: &mut [u8; TRNG_BLOCK_SIZE_BYTES],
    ) {
        let regs = T::regs();
        let ehr_data_regs = [
            regs.ehr_data0(),
            regs.ehr_data1(),
            regs.ehr_data2(),
            regs.ehr_data3(),
            regs.ehr_data4(),
            regs.ehr_data5(),
        ];

        for (i, reg) in ehr_data_regs.iter().enumerate() {
            buffer[i * 4..i * 4 + 4].copy_from_slice(&reg.read().to_ne_bytes());
        }
    }

    /// Waits without a deadline, then fills `buffer` from one complete result; inherits invalid-state panic.
    fn blocking_read_ehr_registers_into_array(
        &mut self,
        buffer: &mut [u8; TRNG_BLOCK_SIZE_BYTES],
    ) {
        self.blocking_wait_for_successful_generation();
        self.read_ehr_registers_into_array(buffer);
    }

    /// Fills `destination` from successive entropy blocks, discarding any unused final-block bytes.
    /// Empty output is a no-op. Cancellation disables the IRQ/source and resets the counter; already copied
    /// output remains changed. Invalid/reset results restart generation; no deadline or error result is provided.
    pub async fn fill_bytes(
        &mut self,
        destination: &mut [u8],
    ) {
        if destination.is_empty() {
            return; // Nothing to fill
        }

        // Also stop the source and IRQ when the caller cancels this future.
        let _cleanup = OnDrop::new(|| {
            T::Interrupt::disable();
            Self::stop_rng_inner();
        });
        self.start_rng();
        self.enable_irq();

        let mut bytes_transferred = 0usize;
        let mut buffer = [0u8; TRNG_BLOCK_SIZE_BYTES];

        let regs = T::regs();

        let trng_busy_register = regs.trng_busy();
        let trng_valid_register = regs.trng_valid();

        let waker = T::waker();

        let destination_length = destination.len();

        poll_fn(|context| {
            waker.register(context.waker());
            if bytes_transferred == destination_length {
                Poll::Ready(())
            } else {
                if trng_busy_register.read().trng_busy() {
                    Poll::Pending
                } else {
                    // If woken up and EHR is *not* valid, assume the trng has been reset and reinitialize, restart.
                    if trng_valid_register.read().ehr_valid().not() {
                        self.initialize_rng();
                        self.start_rng();
                        return Poll::Pending;
                    }
                    self.read_ehr_registers_into_array(&mut buffer);
                    let remaining = destination_length - bytes_transferred;
                    if remaining > TRNG_BLOCK_SIZE_BYTES {
                        destination[bytes_transferred..bytes_transferred + TRNG_BLOCK_SIZE_BYTES]
                            .copy_from_slice(&buffer);
                        bytes_transferred += TRNG_BLOCK_SIZE_BYTES
                    } else {
                        destination[bytes_transferred..bytes_transferred + remaining]
                            .copy_from_slice(&buffer[0..remaining]);
                        bytes_transferred += remaining
                    }
                    if bytes_transferred == destination_length {
                        Poll::Ready(())
                    } else {
                        Poll::Pending
                    }
                }
            }
        })
        .await
    }

    /// Fills `destination` synchronously and stops the source; empty output is a no-op.
    /// May wait indefinitely or panic on idle-invalid hardware state; panic can leave the source enabled.
    pub fn blocking_fill_bytes(
        &mut self,
        destination: &mut [u8],
    ) {
        if destination.is_empty() {
            return; // Nothing to fill
        }
        self.start_rng();

        let mut buffer = [0u8; TRNG_BLOCK_SIZE_BYTES];

        for chunk in destination.chunks_mut(TRNG_BLOCK_SIZE_BYTES) {
            self.blocking_wait_for_successful_generation();
            self.blocking_read_ehr_registers_into_array(&mut buffer);
            chunk.copy_from_slice(&buffer[..chunk.len()])
        }
        self.stop_rng()
    }

    /// Returns one word from EHR_DATA5 after blocking generation, discarding the other160 bits.
    /// No deadline; invalid-state panic can leave the source enabled.
    pub fn blocking_next_u32(&mut self) -> u32 {
        let regs = T::regs();
        self.start_rng();
        self.blocking_wait_for_successful_generation();
        // 12.12.3 After successful generation, read the last result register, EHR_DATA[5] to
        // clear all of the result registers.
        let result = regs.ehr_data5().read();
        self.stop_rng();
        result
    }

    /// Returns EHR_DATA4 as low32 bits and EHR_DATA5 as high32 bits after blocking generation.
    /// No deadline; invalid-state panic can leave the source enabled.
    pub fn blocking_next_u64(&mut self) -> u64 {
        let regs = T::regs();
        self.start_rng();
        self.blocking_wait_for_successful_generation();

        let low = regs.ehr_data4().read() as u64;
        // 12.12.3 After successful generation, read the last result register, EHR_DATA[5] to
        // clear all of the result registers.
        let result = (regs.ehr_data5().read() as u64) << 32 | low;
        self.stop_rng();
        result
    }
}

impl<'d, T: Instance> rand_core_06::RngCore for Trng<'d, T> {
    /// Returns a blocking-generated word; inherits the hardware wait and panic behavior.
    fn next_u32(&mut self) -> u32 { self.blocking_next_u32() }

    /// Returns a blocking-generated double word; inherits the hardware wait and panic behavior.
    fn next_u64(&mut self) -> u64 { self.blocking_next_u64() }

    /// Fills `dest` through the blocking hardware path; may stall or panic rather than report an RNG error.
    fn fill_bytes(
        &mut self,
        dest: &mut [u8],
    ) {
        self.blocking_fill_bytes(dest);
    }

    /// Fills `dest` synchronously and returns Ok; hardware stalls/panics are not converted into rand errors.
    fn try_fill_bytes(
        &mut self,
        dest: &mut [u8],
    ) -> Result<(), rand_core_06::Error> {
        self.blocking_fill_bytes(dest);
        Ok(())
    }
}

impl<'d, T: Instance> rand_core_06::CryptoRng for Trng<'d, T> {}

impl<'d, T: Instance> rand_core_09::RngCore for Trng<'d, T> {
    /// Returns a blocking-generated word; inherits the hardware wait and panic behavior.
    fn next_u32(&mut self) -> u32 { self.blocking_next_u32() }

    /// Returns a blocking-generated double word; inherits the hardware wait and panic behavior.
    fn next_u64(&mut self) -> u64 { self.blocking_next_u64() }

    /// Fills `dest` through the blocking hardware path; may stall or panic rather than report an RNG error.
    fn fill_bytes(
        &mut self,
        dest: &mut [u8],
    ) {
        self.blocking_fill_bytes(dest);
    }
}

impl<'d, T: Instance> rand_core_09::CryptoRng for Trng<'d, T> {}

/// TRNG interrupt handler.
pub struct InterruptHandler<T: Instance> {
    /// Binds this zero-sized handler to the owned TRNG instance.
    _trng: PhantomData<T>,
}

impl<T: Instance> interrupt::typelevel::Handler<T::Interrupt> for InterruptHandler<T> {
    /// Handles one prioritized status: EHR wakes, CRNGT/VN clear with warning, autocorrelation resets and wakes.
    /// # Safety
    /// Must run only for the bound instance IRQ; application code must not concurrently alter its registers.
    unsafe fn on_interrupt() {
        let regs = T::regs();
        let isr = regs.rng_isr().read();
        if isr.ehr_valid() {
            regs.rng_icr().write(|w| {
                w.set_ehr_valid(true);
            });
            T::waker().wake();
        } else if isr.crngt_err() {
            warn!("TRNG CRNGT error! Increase sample count to reduce likelihood");
            regs.rng_icr().write(|w| {
                w.set_crngt_err(true);
            });
        } else if isr.vn_err() {
            warn!("TRNG Von-Neumann balancer error! Increase sample count to reduce likelihood");
            regs.rng_icr().write(|w| {
                w.set_vn_err(true);
            });
        } else if isr.autocorr_err() {
            // 12.12.5. List of Registers
            // ...
            // TRNG: RNG_ISR Register
            // ...
            // AUTOCORR_ERR: 1 indicates Autocorrelation test failed four times in a row.
            // When set, RNG ceases functioning until next reset
            warn!("TRNG Autocorrect error! Resetting TRNG. Increase sample count to reduce likelihood");
            regs.trng_sw_reset().write(|w| {
                w.set_trng_sw_reset(true);
            });
            // Fixed delay is required after TRNG soft reset, this read is sufficient.
            regs.trng_sw_reset().read();
            // Wake up to reinitialize and restart the TRNG.
            T::waker().wake();
        }
    }
}
